    reportNumber: "CAB SA-155", route: { en: "Los Angeles → Chicago", zh: "洛杉矶 → 芝加哥" }, location: { en: "Bryce Canyon, Utah, United States", zh: "美国犹他州布莱斯峡谷附近" }, agency: "CAB",
    summary: { en: "A fire developed in flight after fuel escaped from a vent system and was drawn toward the cabin-heater air intake. The crew diverted toward Bryce Canyon, but the fire damaged the aircraft before an emergency landing could be completed.", zh: "燃油从通气系统逸出后被带向客舱加热器进气口，引发空中火灾。机组转向布莱斯峡谷机场，但飞机在完成紧急着陆前已受到严重影响。" },
    findings: [{ en: "Fuel discharged from the alternate tank vent accumulated near the heater intake.", zh: "从备用油箱通气口排出的燃油聚集在加热器进气口附近。" }, { en: "The resulting fire spread while the crew attempted an emergency descent.", zh: "机组紧急下降期间，火势继续蔓延。" }, { en: "The DC-6 fleet was grounded while the vent and heater arrangement was modified.", zh: "DC-6机队随后停飞，以修改通气与加热器布局。" }],
    safetyImpact: { en: "The investigation produced urgent DC-6 fuel-vent and heater-intake design changes and became an important early example of fleet-wide corrective action.", zh: "调查促成DC-6燃油通气口与加热器进气口的紧急设计修改，成为早期机队级整改的重要案例。" },
    timeline: [{ time: "12:21", text: { en: "Flight 608 departed Los Angeles.", zh: "608号班机从洛杉矶起飞。" } }, { time: "Cruise", text: { en: "The crew reported an in-flight fire and began descending.", zh: "机组报告空中火灾并开始下降。" } }, { time: "Approach", text: { en: "The crew attempted to reach Bryce Canyon Airport.", zh: "机组尝试抵达布莱斯峡谷机场。" } }, { time: "1947", text: { en: "The CAB issued findings and required design action.", zh: "CAB发布调查结论并推动设计整改。" } }],
    chart: [{ minute: 0, altitude: 19000, speed: 250 }, { minute: 3, altitude: 15000, speed: 245 }, { minute: 6, altitude: 11000, speed: 235 }, { minute: 9, altitude: 8500, speed: 220 }, { minute: 12, altitude: 7000, speed: 200 }],
