    operator: { en: "Northwest Orient Airlines", zh: "西北东方航空" }, phase: { en: "Cruise", zh: "巡航" }, personsOnBoard: 58, reportNumber: "CAB File 1-0075",
    route: { en: "New York → Seattle (via Minneapolis and Spokane)", zh: "纽约 → 西雅图（经明尼阿波利斯和斯波坎）" }, location: { en: "Lake Michigan near South Haven, Michigan", zh: "密歇根州南黑文附近的密歇根湖" }, agency: "CAB",
    summary: { en: "During a night crossing of Lake Michigan, the flight encountered a strong storm system and requested a lower altitude. Contact was then lost. Only limited debris was recovered, and the main wreckage has not been conclusively located.", zh: "航班夜间飞越密歇根湖时遭遇强风暴并请求降低高度，随后失去联系。仅发现有限残骸，主体残骸至今没有得到确定定位。" },
    findings: [{ en: "Severe convective weather was present along the route.", zh: "航路上存在强烈对流天气。" }, { en: "The aircraft requested a descent shortly before contact ended.", zh: "飞机在失联前不久请求下降。" }, { en: "Because the main wreckage was unavailable, the CAB could not determine a probable cause.", zh: "由于无法取得主体残骸，CAB未能确定事故原因。" }],
    safetyImpact: { en: "The unresolved loss highlights the importance of weather avoidance, position tracking and recoverable flight evidence over large bodies of water.", zh: "这起未解事故说明在大面积水域上空运行时，天气绕飞、位置追踪和可恢复飞行证据的重要性。" },
    timeline: [{ time: "19:30", text: { en: "The flight departed New York.", zh: "航班从纽约起飞。" } }, { time: "23:51", text: { en: "The crew reported near Battle Creek.", zh: "机组在巴特尔克里克附近报告位置。" } }, { time: "00:13", text: { en: "The crew requested a lower altitude because of weather.", zh: "机组因天气请求降低高度。" } }, { time: "After 00:13", text: { en: "Radio contact was not re-established.", zh: "此后未能恢复无线电联系。" } }],
