    route: { en: "Denver → Salt Lake City", zh: "丹佛 → 盐湖城" }, location: { en: "Medicine Bow Peak, Wyoming, United States", zh: "美国怀俄明州梅迪辛博峰" }, agency: "CAB",
    summary: { en: "While crossing southern Wyoming, Flight 409 left the protected airway and reached mountainous terrain near Medicine Bow Peak. Weather, route position and the crew's navigation decisions were central to the investigation.", zh: "409号班机飞越怀俄明州南部时偏离受保护航路，在梅迪辛博峰附近进入山区地形。天气、航路位置和机组导航决策是调查重点。" },
    findings: [{ en: "The aircraft was substantially west of the prescribed airway.", zh: "飞机明显偏在规定航路以西。" }, { en: "No pre-impact mechanical failure was established.", zh: "未确认撞击前存在机械故障。" }, { en: "The CAB could not determine why the crew deviated from the safe route.", zh: "CAB未能确定机组为何偏离安全航路。" }],
    safetyImpact: { en: "The case reinforced airway adherence, position verification and minimum-altitude discipline over mountainous terrain.", zh: "该事故强化了山区飞行中遵守航路、核实位置和保持最低安全高度的重要性。" },
    timeline: [{ time: "06:33", text: { en: "The flight departed Denver.", zh: "航班从丹佛起飞。" } }, { time: "En route", text: { en: "The DC-4 crossed southern Wyoming in cloud.", zh: "DC-4在云中飞越怀俄明州南部。" } }, { time: "07:26", text: { en: "The aircraft reached terrain near Medicine Bow Peak.", zh: "飞机在梅迪辛博峰附近进入地形。" } }, { time: "1957", text: { en: "The CAB issued its final findings.", zh: "CAB发布最终调查结论。" } }],
    chart: [{ minute: 0, altitude: 8500, speed: 205 }, { minute: 8, altitude: 9000, speed: 210 }, { minute: 16, altitude: 9500, speed: 210 }, { minute: 24, altitude: 10000, speed: 205 }, { minute: 30, altitude: 11200, speed: 200 }],
