    operator: { en: "Trans World Airlines", zh: "环球航空（TWA）" }, phase: { en: "Cruise / mid-air collision", zh: "巡航／空中相撞" }, personsOnBoard: 70, reportNumber: "CAB SA-320",
    route: { en: "Los Angeles → Kansas City", zh: "洛杉矶 → 堪萨斯城" }, location: { en: "Grand Canyon, Arizona, United States", zh: "美国亚利桑那州大峡谷" }, agency: "CAB",
    summary: { en: "Flight 2 and United Flight 718 collided while operating outside controlled airspace near the Grand Canyon. The investigation examined see-and-avoid limitations, traffic information and the structure of the U.S. air-traffic system.", zh: "2号班机与联合航空718号班机在大峡谷附近的非管制空域相撞。调查分析了“看见并避让”的局限、交通信息以及美国空管体系结构。" },
    findings: [{ en: "Both aircraft were operating under visual separation outside positive control.", zh: "两机在主动管制范围外依靠目视保持间隔。" }, { en: "The crews did not see each other in sufficient time to avoid collision.", zh: "双方机组未能及时发现对方并避免相撞。" }, { en: "Cockpit visibility and intervening cloud reduced the effectiveness of see-and-avoid.", zh: "驾驶舱视野与云层降低了目视避让的有效性。" }],
    safetyImpact: { en: "The disaster accelerated nationwide radar coverage, positive control at high altitude and the legislation that created the Federal Aviation Agency in 1958.", zh: "该事故加速了全国雷达覆盖、高空主动管制，以及1958年成立美国联邦航空局的立法。" },
    timeline: [{ time: "09:01", text: { en: "TWA Flight 2 departed Los Angeles.", zh: "TWA 2号班机从洛杉矶起飞。" } }, { time: "Cruise", text: { en: "The flight operated near cloud tops over the Grand Canyon.", zh: "航班在大峡谷上空云顶附近飞行。" } }, { time: "10:30", text: { en: "Flight 2 and United 718 collided.", zh: "2号班机与联合航空718号班机相撞。" } }, { time: "1958", text: { en: "U.S. aviation legislation established a new federal agency and expanded positive control.", zh: "美国航空立法成立新的联邦机构并扩大主动管制。" } }],
    chart: [{ minute: 0, altitude: 19000, speed: 300 }, { minute: 5, altitude: 20000, speed: 305 }, { minute: 10, altitude: 21000, speed: 310 }, { minute: 15, altitude: 21000, speed: 310 }, { minute: 20, altitude: 21000, speed: 310 }],
    chartNote: { en: "Schematic cruise profile based on the CAB report; values are not a flight-recorder trace.", zh: "依据CAB报告制作的巡航示意图；数值并非飞行记录器轨迹。" }, image: constellationArchiveImage,
    sourceUrl: "https://www.faa.gov/lessons_learned/transport_airplane/accidents/N6902C", reportUrl: "https://rosap.ntl.bts.gov/view/dot/33556",
