    route: { en: "Los Angeles → Chicago", zh: "洛杉矶 → 芝加哥" }, location: { en: "Grand Canyon, Arizona, United States", zh: "美国亚利桑那州大峡谷" }, agency: "CAB",
    summary: { en: "United Flight 718 and TWA Flight 2 collided in uncontrolled airspace near the Grand Canyon. This companion record presents the DC-7 side of the same event and links it to the broader air-traffic-control reforms.", zh: "联合航空718号班机与TWA 2号班机在大峡谷附近的非管制空域相撞。本页从DC-7一方记录同一事件，并关联其推动的空管改革。" },
    findings: [{ en: "The DC-7 was operating outside positive air-traffic control.", zh: "这架DC-7当时在主动空管范围外运行。" }, { en: "The two aircraft converged at similar altitude and neither crew avoided the conflict in time.", zh: "两机在相近高度交汇，双方机组均未能及时避让。" }, { en: "The existing system could not reliably separate fast airliners across the route network.", zh: "当时的系统无法在航路网络中可靠分隔高速客机。" }],
    safetyImpact: { en: "The same investigation led to major U.S. radar, controlled-airspace and institutional reforms, including creation of the Federal Aviation Agency.", zh: "同一调查推动美国雷达、管制空域和机构改革，包括成立联邦航空局。" },
    timeline: [{ time: "09:04", text: { en: "United Flight 718 departed Los Angeles.", zh: "联合航空718号班机从洛杉矶起飞。" } }, { time: "Cruise", text: { en: "The DC-7 proceeded east near the Grand Canyon.", zh: "DC-7在大峡谷附近向东飞行。" } }, { time: "10:30", text: { en: "United 718 and TWA 2 collided.", zh: "联合航空718号班机与TWA 2号班机相撞。" } }, { time: "1958", text: { en: "Federal reforms expanded radar and positive control.", zh: "联邦改革扩大了雷达和主动管制。" } }],
    chart: [{ minute: 0, altitude: 21000, speed: 330 }, { minute: 5, altitude: 21000, speed: 330 }, { minute: 10, altitude: 21000, speed: 330 }, { minute: 15, altitude: 21000, speed: 330 }, { minute: 20, altitude: 21000, speed: 330 }],
    chartNote: { en: "Schematic cruise profile based on the CAB report; values are not a flight-recorder trace.", zh: "依据CAB报告制作的巡航示意图；数值并非飞行记录器轨迹。" }, image: dc4ArchiveImage,
    sourceUrl: "https://www.faa.gov/lessons_learned/transport_airplane/accidents/N6902C", reportUrl: "https://rosap.ntl.bts.gov/view/dot/33556",
