    route: { en: "Bristol Filton → test flight → Bristol Filton", zh: "布里斯托尔菲尔顿 → 试飞 → 布里斯托尔菲尔顿" }, location: { en: "Downend, near Bristol, United Kingdom", zh: "英国布里斯托尔附近唐恩德" }, agency: "UK Ministry of Transport and Civil Aviation",
    summary: { en: "This was a development test flight, not a passenger service. While returning to Filton in poor weather, the prototype Britannia descended below a safe approach path before reaching the runway.", zh: "这是一次研制试飞，并非载客航班。原型“不列颠”客机在恶劣天气中返回菲尔顿时，于到达跑道前下降至安全进近航迹以下。" },
    findings: [{ en: "The flight was conducting development work rather than commercial transport.", zh: "该飞行执行研制任务，而非商业运输。" }, { en: "Visibility and cloud complicated the return to Filton.", zh: "能见度和云层增加了返回菲尔顿的难度。" }, { en: "The aircraft descended below the required terrain-clearance profile.", zh: "飞机下降至规定的地形净空剖面以下。" }],
    safetyImpact: { en: "The event reinforced disciplined instrument-approach monitoring and terrain clearance during development and acceptance flying.", zh: "该事故强化了研制与验收飞行中对仪表进近和地形净空的严格监控。" },
