export const accidents: Accident[] = accidentRecords.map((accident) => {
  const metrics = caseMetrics[accident.slug];
  if (!metrics) throw new Error(`Missing sorting metrics for ${accident.slug}`);
  return { ...accident, ...metrics };
});

export function getAccident(slug: string) { return accidents.find((item) => item.slug === slug); }
